svg.script:
(() => {
  'use strict';
  const token = new URL(location.href).searchParams.get('svg-asset');
  if (!token || parent === window) return;
  const root = document.documentElement.cloneNode(true);
  root.querySelectorAll('script').forEach(script => script.remove());
  parent.postMessage({ type: 'svg-asset', token, url: location.href,
    source: new XMLSerializer().serializeToString(root) }, '*');
})();
